package handlers

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
)

// TestContract_WebPayloads_Auth verifies that the exact JSON payloads generated by
// web/src/lib/api.ts decode into auth-service request structs under DisallowUnknownFields.
func TestContract_WebPayloads_Auth(t *testing.T) {
	t.Run("signup payload decodes into signupRequest", func(t *testing.T) {
		payload := []byte(`{
			"full_name": "Omar Maarouf",
			"email": "student@example.com",
			"phone": "01012345678",
			"password": "SecurePassword123!"
		}`)
		var req signupRequest
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&req); err != nil {
			t.Fatalf("failed to decode signup payload: %v", err)
		}
		if req.Email != "student@example.com" || req.FullName != "Omar Maarouf" || req.Phone != "01012345678" {
			t.Fatalf("unexpected fields in decoded signupRequest: %+v", req)
		}
	})

	t.Run("verify-otp payload decodes into verifyOTPRequest", func(t *testing.T) {
		payload := []byte(`{
			"email": "student@example.com",
			"code": "123456",
			"pending_id": "pending-uuid-123"
		}`)
		var req verifyOTPRequest
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&req); err != nil {
			t.Fatalf("failed to decode verify-otp payload: %v", err)
		}
		if req.Email != "student@example.com" || req.Code != "123456" || req.PendingID != "pending-uuid-123" {
			t.Fatalf("unexpected fields in decoded verifyOTPRequest: %+v", req)
		}
	})

	t.Run("resend-otp old payload with pending_id is rejected by resendSignupRequest", func(t *testing.T) {
		// Old payload from web/ sent pending_id which was rejected by backend.
		oldPayload := []byte(`{
			"email": "student@example.com",
			"pending_id": "pending-uuid-123"
		}`)
		var req resendSignupRequest
		dec := json.NewDecoder(bytes.NewReader(oldPayload))
		dec.DisallowUnknownFields()
		err := dec.Decode(&req)
		if err == nil {
			t.Fatal("expected DisallowUnknownFields to reject old resend payload containing pending_id, but got nil")
		}
		if !strings.Contains(err.Error(), `unknown field "pending_id"`) {
			t.Fatalf("expected unknown field pending_id error, got: %v", err)
		}
	})

	t.Run("resend-otp valid web payload decodes into resendSignupRequest", func(t *testing.T) {
		payload := []byte(`{
			"email": "student@example.com"
		}`)
		var req resendSignupRequest
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&req); err != nil {
			t.Fatalf("failed to decode resend payload: %v", err)
		}
		if req.Email != "student@example.com" {
			t.Fatalf("unexpected email in decoded resendSignupRequest: %q", req.Email)
		}
	})

	t.Run("login payload decodes into loginRequest", func(t *testing.T) {
		payload := []byte(`{
			"email": "student@example.com",
			"password": "SecurePassword123!",
			"device_id": "web-device-uuid",
			"device_label": "Firefox on Linux"
		}`)
		var req loginRequest
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&req); err != nil {
			t.Fatalf("failed to decode login payload: %v", err)
		}
		if req.Email != "student@example.com" || req.DeviceID != "web-device-uuid" {
			t.Fatalf("unexpected fields in decoded loginRequest: %+v", req)
		}
	})

	t.Run("refresh payload decodes into refreshRequest", func(t *testing.T) {
		payload := []byte(`{}`)
		var req refreshRequest
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&req); err != nil {
			t.Fatalf("failed to decode refresh payload: %v", err)
		}
	})
}
